using V=std::array<double,3>;
static void ck(bool q,const std::string&m){if(!q)throw std::runtime_error(m);}
static V sub(V a,V b){return {a[0]-b[0],a[1]-b[1],a[2]-b[2]};} static double dot(V a,V b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];} static int sign(double x){return (x>0)-(x<0);} static V cross(V a,V b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};} static double vol6(V a,V b,V c,V d){return dot(sub(b,a),cross(sub(c,a),sub(d,a)));}
static std::string materialText(){return "material regional_contact_probe { parameter density : kg/m^3 = 1000 in [1000,1000]; parameter mu : Pa = 50000 in [50000,50000]; parameter lambda : Pa = 500000 in [500000,500000]; model neo_hookean; energy = neo_hookean(mu,lambda); valid = J() - 0.1; supports fem; interface {static_friction=0;dynamic_friction=0;restitution=0;adhesion=0;} limits {minimum_J=0.1;maximum_J=10;maximum_stress=1e9;maximum_energy_density=1e9;} }";}
static std::array<std::uint64_t,4> identityWords(const std::string& label,const void* tail,std::size_t bytes){
    std::string payload=label;
    payload.append(static_cast<const char*>(tail),bytes);
    std::array<unsigned char,CC_SHA256_DIGEST_LENGTH> digest{};
    ck(CC_SHA256(payload.data(),static_cast<CC_LONG>(payload.size()),digest.data())!=nullptr,"SHA-256 failed");
    std::array<std::uint64_t,4> words{};
    for(unsigned w=0;w<4;w++){for(unsigned b=0;b<8;b++)words[w]=(words[w]<<8u)|digest[8u*w+b];if(words[w]==0u)words[w]=w+1u;}
    return words;
}
static nm::ObjectSource makeObject(const assets::Asset&a,const std::string&name,V translation,double vx){nm::ObjectSource o;o.name=name;o.representation=nm::Representation::fem;o.materialIndex=0;o.twoWayCoupling=true;o.adaptive=false;o.mixedFEM=false;o.deformableContact=true;o.deformableSelfContact=false;o.characteristicLength=.03;o.femInitialVelocity={vx,0,0};o.femNodes.reserve(a.nodeCount);for(uint32_t i=0;i<a.nodeCount;i++)o.femNodes.push_back({a.nodes[i].local[0]+translation[0],a.nodes[i].local[1]+translation[1],a.nodes[i].local[2]+translation[2]});o.tetrahedra.reserve(a.tetCount);for(uint32_t i=0;i<a.tetCount;i++){auto t=a.tets[i].nodes;if(vol6(o.femNodes[t[0]],o.femNodes[t[1]],o.femNodes[t[2]],o.femNodes[t[3]])<0)std::swap(t[1],t[2]);o.tetrahedra.push_back({t});}std::vector<uint8_t> boundary(a.nodeCount);for(uint32_t i=0;i<a.boundaryCount;i++)for(auto n:a.boundary[i].nodes)boundary[n]=1;for(uint32_t i=0;i<a.nodeCount;i++)if(boundary[i])o.femContactNodes.push_back(i);
    // Test-only explicit unstressed current-pose reference; this is not an anatomical unloaded-state claim.
    o.femReferenceNodes=o.femNodes;
    o.femMaterialIndices.assign(o.tetrahedra.size(),o.materialIndex);
    const std::string materialIdentity=name+"|"+materialText()+"|regional-material-v1";
    o.femMaterialSourceIdentity=identityWords(materialIdentity,o.femMaterialIndices.data(),o.femMaterialIndices.size()*sizeof(o.femMaterialIndices.front()));
    const std::string referenceIdentity=name+"|explicit-current-pose-reference-v1|"+materialIdentity;
    o.femReferenceSourceIdentity=identityWords(referenceIdentity,o.femReferenceNodes.data(),o.femReferenceNodes.size()*sizeof(o.femReferenceNodes.front()));
    o.femReferenceDisplacementGradient=true;
    return o;}
static bool same(const auto&a,const auto&b){return a.size()==b.size()&&(a.empty()||std::memcmp(a.data(),b.data(),a.size()*sizeof(a[0]))==0);}static uint32_t fbits(float x){uint32_t b=0;std::memcpy(&b,&x,sizeof(b));return b;}
static void failLate(id<MTLDevice>d,id<MTLCommandBuffer>c,id<MTLBuffer>dst){MRMetalWorldStatusGPU s{};s.code=MR_STEP_DID_NOT_CONVERGE;id<MTLBuffer>src=[d newBufferWithBytes:&s length:sizeof(s) options:MTLResourceStorageModeShared];id<MTLBlitCommandEncoder>b=[c blitCommandEncoder];[b copyFromBuffer:src sourceOffset:0 toBuffer:dst destinationOffset:0 size:sizeof(s)];[b endEncoding];[c addCompletedHandler:^(id<MTLCommandBuffer>x){(void)x;(void)src;}];}
static void transact(nm::Runtime&r,id<MTLDevice>d,id<MTLCommandQueue>q,id<MTLBuffer>ws,uint32_t step,bool reject){auto*s=(MRMetalWorldStatusGPU*)ws.contents;*s={};s->code=MR_STEP_SUCCESS;id<MTLCommandBuffer>c=[q commandBuffer];nm::EncodeRequest a{};a.commandBuffer=(__bridge void*)c;a.environmentStatuses=(__bridge void*)ws;a.controlStep=step;a.physicsSubstep=0;a.physicsSubsteps=1;a.timestepSeconds=r.timestepSeconds();a.phase=nm::EncodePhase::preDynamics;auto e=r.encode(a);ck(e.encoded,"pre: "+e.message);if(reject)failLate(d,c,ws);a.phase=nm::EncodePhase::postCommit;e=r.encode(a);ck(e.encoded,"post: "+e.message);[c commit];[c waitUntilCompleted];ck(c.status==MTLCommandBufferStatusCompleted,"Metal command failed");}
static std::vector<nm_float4> readMechanicalResidual(nm::Runtime&r,id<MTLCommandQueue>q,size_t rows){
    id<MTLBuffer>src=(__bridge id<MTLBuffer>)r.femMechanicalResidualBuffer();
    ck(src,"mechanical residual buffer unavailable");
    const size_t bytes=rows*sizeof(nm_float4);
    ck(src.length>=bytes,"mechanical residual buffer shorter than FEM rows");
    id<MTLBuffer>dst=[src.device newBufferWithLength:bytes options:MTLResourceStorageModeShared];
    ck(dst,"mechanical residual readback allocation failed");
    id<MTLCommandBuffer>cb=[q commandBuffer];
    id<MTLBlitCommandEncoder>blit=[cb blitCommandEncoder];
    ck(blit,"mechanical residual readback blit unavailable");
    [blit copyFromBuffer:src sourceOffset:0 toBuffer:dst destinationOffset:0 size:bytes];
    [blit endEncoding]; [cb commit]; [cb waitUntilCompleted];
    ck(cb.status==MTLCommandBufferStatusCompleted,"mechanical residual readback failed");
    const auto*data=static_cast<const nm_float4*>(dst.contents);
    return std::vector<nm_float4>(data,data+rows);
}

